const numberIds=['scoreDoNow','scoreAltNow','scoreDoLater','scoreAltLater','scoreHorizon','nowWeight','altRecovery','smallNow','smallLater'];
function updateWeight(){const w=Number($('nowWeight').value);put('weightOut',`${w}% now · ${100-w}% later`)}$('nowWeight').addEventListener('input',updateWeight);
function scoreValue(id){return $(id).value===''?null:Number($(id).value)}
function combined(now,later,w){if(w===1)return now;if(w===0)return later;return now===null||later===null?null:now*w+later*(1-w)}
function addText(parent,tag,text,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;parent.append(n);return n}
function renderNumbers(){if(!current)return;const d=current;numberIds.forEach(id=>d[id]=$(id).value);const w=Number(d.nowWeight)/100,now=scoreValue('scoreDoNow'),later=scoreValue('scoreDoLater'),anow=scoreValue('scoreAltNow'),alater=scoreValue('scoreAltLater');const a=combined(now,later,w),b=combined(anow,alater,w);const box=$('numberDashboard');box.replaceChildren();addText(box,'p','Calculated costs. Your happiness forecasts.','eyebrow');const grid=document.createElement('div');grid.className='score-grid';box.append(grid);for(const [title,score] of [[d.task,a],[d.alt,b]]){const card=document.createElement('div');card.className='score-card';addText(card,'strong',title);const n=addText(card,'span',score===null?'—':score.toFixed(1),'score-number');addText(n,'small',' / 10');const bar=document.createElement('div');bar.className='score-bar';bar.setAttribute('aria-hidden','true');const fill=document.createElement('span');fill.style.width=(score===null?0:score*10)+'%';bar.append(fill);card.append(bar);addText(card,'p',score===null?'Add the ratings used by your chosen weight.':'Combined happiness estimate · your inputs','helper');grid.append(card)}
const label=a===null||b===null?'Add your happiness ratings to compare scores.':Math.abs(a-b)<.05?'Your weighted happiness ratings are tied.':`Your ratings favor ${a>b?'the first option':'the alternative'} by ${Math.abs(a-b).toFixed(1)} / 10 at ${d.nowWeight}% now and ${100-Number(d.nowWeight)}% later.`;addText(box,'p',label,'metric-line');addText(box,'p',`“Later” = ${d.scoreHorizon}. This score is not an objective happiness prediction. It does not include money, time, or effort; those remain separate so you can see the tradeoff.`,'helper');
const t1=Number(d.minutes)+Number(d.recovery||0),t2=Number(d.altMinutes)+Number(d.altRecovery||0),dt=t1-t2,dm=Number(d.money||0)-Number(d.altMoney),de=Number(d.energy)-Number(d.altEffort);
const lines=[dt===0?'Time difference: 0 minutes.':`${dt>0?'Alternative':'First option'} saves ${Math.abs(dt)} minutes, including entered recovery time.`,dm===0?'Money difference: $0.00.':`${dm>0?'Alternative':'First option'} saves ${money(Math.abs(dm))}.`,de===0?'Effort ratings: equal on your 1–5 scale.':`${de>0?'Alternative':'First option'} has ${Math.abs(de)} point${Math.abs(de)===1?'':'s'} lower expected effort on your 1–5 scale. This is not a measured amount of energy saved.`];lines.forEach(text=>addText(box,'p',text,'metric-line'));
const wrap=document.createElement('div');wrap.className='math-table';const table=document.createElement('table');const caption=document.createElement('caption');caption.textContent='Your input comparison';table.append(caption);const head=document.createElement('thead'),hr=document.createElement('tr');['Option','Now / 10','Later / 10','Time¹','Cost','Effort²'].forEach(h=>{const th=addText(hr,'th',h);th.scope='col'});head.append(hr);table.append(head);const body=document.createElement('tbody');const rows=[[d.task,now,later,t1,money(Number(d.money||0)),d.energy+'/5'],[d.alt,anow,alater,t2,money(Number(d.altMoney)),d.altEffort+'/5']];if(d.smallOption&&!(d.decisionType==='relationship'&&d.interest==='declined'))rows.push([d.smallOption,scoreValue('smallNow'),scoreValue('smallLater'),d.smallMinutes===''?null:Number(d.smallMinutes),d.smallMoney===''?'Not entered':money(Number(d.smallMoney)),'Not rated']);for(const row of rows){const tr=document.createElement('tr');row.forEach((v,i)=>addText(tr,i===0?'th':'td',v===null?'Not entered':i===3?v+' min':String(v)));body.append(tr)}table.append(body);wrap.append(table);box.append(wrap);addText(box,'p','¹ Main options include entered recovery. Third option time excludes recovery. ² Subjective effort, not calories or biological energy.','helper');const formula=addText(box,'details','');addText(formula,'summary','Show the calculation');const f=x=>x===null?'missing':x.toFixed(1);addText(formula,'p',`First option: (${f(now)} × ${w.toFixed(1)}) + (${f(later)} × ${(1-w).toFixed(1)}) = ${f(a)}. Alternative: (${f(anow)} × ${w.toFixed(1)}) + (${f(alater)} × ${(1-w).toFixed(1)}) = ${f(b)}. A rating with zero weight is ignored. You choose the ratings and the weights; this formula is not a validated psychological model.`,'formula');
if(d.smallOption&&!(d.decisionType==='relationship'&&d.interest==='declined')){const third=combined(scoreValue('smallNow'),scoreValue('smallLater'),w);addText(box,'p',`Third option combined score: ${third===null?'not enough ratings':third.toFixed(1)+' / 10'}.`,'metric-line')}
if(d.decisionType==='relationship'&&d.interest==='declined')addText(box,'p','A happiness score does not override their answer. They have declined or asked for space.','metric-line');put('happiness',`Your happiness ratings: first option ${f(now)}/10 now and ${f(later)}/10 in ${d.scoreHorizon}; alternative ${f(anow)}/10 now and ${f(alater)}/10 later. These are your estimates, with ${d.confidence} confidence.`);d.profileSummary=`NUMERIC COMPARISON\nFirst option: ${f(a)}/10. Alternative: ${f(b)}/10. Weight: ${d.nowWeight}% now, ${100-Number(d.nowWeight)}% in ${d.scoreHorizon}. Based on your forecasts.\n${lines.join('\n')}\n\n`+[energyPlan().text,$('scenarioText').textContent,$('scenarioMath').textContent,d.smallOption?'Third option: '+$('smallText').textContent:''].filter(Boolean).join('\n\n');
}
$('form').addEventListener('submit',renderNumbers);
const exampleScores={example:{scoreDoNow:6,scoreAltNow:7,scoreDoLater:8,scoreAltLater:6,scoreHorizon:'one month',nowWeight:50},purchaseExample:{scoreDoNow:9,scoreAltNow:5,scoreDoLater:6,scoreAltLater:9,scoreHorizon:'six months',nowWeight:50,smallNow:6,smallLater:8},relationshipExample:{scoreDoNow:7,scoreAltNow:6,scoreDoLater:7,scoreAltLater:6,scoreHorizon:'one month',nowWeight:50,smallNow:7,smallLater:7}};
Object.keys(exampleScores).forEach(id=>$(id).addEventListener('click',()=>{Object.entries(exampleScores[id]).forEach(([key,v])=>$(key).value=v);updateWeight();addPerspective();renderNumbers()}));$('reset').addEventListener('click',updateWeight);
['scoreDoNow','scoreAltNow','scoreDoLater','scoreAltLater','scoreHorizon','nowWeight','altRecovery','smallNow','smallLater'].forEach(id=>$(id).addEventListener('input',()=>{if(current&&$('form').checkValidity()){addPerspective();renderNumbers()}}));
